mapper.select:
SELECT tenant_id,request_id,end_user_id,session_id,run_id,invocation_id,reason,status,
  device_id,browser_id,make_default,pair_dispatched,error,wait_snapshot,revision,created_at,updated_at
FROM nw_browser_connection_requests WHERE tenant_id=#{tenant} AND request_id=#{id}

SELECT tenant_id,request_id,end_user_id,session_id,run_id,invocation_id,reason,status,
  device_id,browser_id,make_default,pair_dispatched,error,wait_snapshot,revision,created_at,updated_at
FROM nw_browser_connection_requests WHERE tenant_id=#{tenant}
  AND status IN ('WAITING','READY','RESUMING','CANCELLING') AND request_id > #{after}
ORDER BY request_id LIMIT #{limit}
